<div class="section-head"><div><span class="eyebrow">DESTINATIONS</span><h1>จัดการจุดหมาย</h1><p>Zone → Country → Route · เลือก Route ให้โปรแกรมทัวร์</p></div><a class="btn" href="<?= (base_url() . ('admin/destinations/'.$kind.'/new')) ?>">＋ เพิ่ม <?= e($kinds[$kind]) ?></a></div>
<nav class="filter-tabs" aria-label="ประเภทจุดหมาย"><?php foreach ($kinds as $key=>$label): ?><a class="<?= $kind===$key ? 'active' : '' ?>" href="<?= (base_url() . ('admin/destinations/'.$key)) ?>"><?= e($label) ?></a><?php endforeach ?></nav>
<section class="panel table-scroll"><table><thead><tr><th>ชื่อ / URL</th><th>อยู่ภายใต้</th><th>การใช้งาน</th><th>Meta title</th><th>จัดการ</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><b><?= e($row['name']) ?></b><small><?= e($row['slug']) ?></small></td><td><?= e($row['parent_name'] ?: '—') ?></td><td><?= (int)$row['child_count'] ?> รายการย่อย · <?= (int)$row['tour_count'] ?> ทัวร์</td><td><?= e($row['meta_title'] ?: 'ใช้ชื่อจุดหมาย') ?></td><td><a class="text-link" href="<?= (base_url() . ('admin/destinations/'.$kind.'/'.$row['id'])) ?>">แก้ไข ↗</a><small><a target="_blank" rel="noopener" href="<?= e(destination_url($row)) ?>">ดูหน้าเว็บ ↗</a></small><?php if ($row['child_count'] || $row['tour_count']): ?><small>ลบไม่ได้: มีรายการย่อยหรือทัวร์ใช้งานอยู่</small><?php else: ?><form method="post" action="<?= (base_url() . ('admin/destinations/'.$kind.'/'.$row['id'].'/delete')) ?>" onsubmit="return confirm(<?= e(json_encode('ลบ “'.$row['name'].'”? ข้อมูลและไฟล์ที่แนบไว้จะถูกลบถาวร', JSON_UNESCAPED_UNICODE)) ?>)"><?= csrf_field() ?><button class="text-button danger" type="submit">ลบ</button></form><?php endif ?></td></tr><?php endforeach ?><?php if (!$rows): ?><tr><td colspan="5" class="empty">ยังไม่มีรายการ เพิ่มรายการแรกได้เลย</td></tr><?php endif ?></tbody></table></section>
